function WorktableDialog:InitData()
    self:InitTabData()
    self:InitWorktableData()
    self:SortWorktableData()
    self:InitArgument()
end

function WorktableDialog:SortWorktableData()
    local worktableData = self:GetWorktableData()
    for i, v in ipairs(worktableData) do
        if i == TabType.CRAFT then
            for _, item in ipairs(v) do
                item.canCraft = self:GetMaxCraftTimes(item.gainId) ~= 0 and true or false
            end
            table.sort(v, function(a, b)
                if a.canCraft ~= b.canCraft then
                    return a.canCraft
                else
                    return checkInt(a.gainId) < checkInt(b.gainId)
                end
            end)
        elseif i == TabType.CONVERT then
            for _, item in ipairs(v) do
                item.canConvert = self:CheckConvert(item)
            end
            table.sort(v, function(a, b)
                if a.canConvert ~= b.canConvert then
                    return a.canConvert
                else
                    return checkInt(a.gainId) < checkInt(b.gainId)
                end
            end)
        elseif i == TabType.FUSION then
            table.sort(v, function(a, b)
                local canFusionA = checkInt(a.num) >= checkInt(a.vo.needNum)
                local canFusionB = checkInt(b.num) >= checkInt(b.vo.needNum)
                if canFusionA ~= canFusionB then
                    return canFusionA
                end
                if a.vo.quality ~= b.vo.quality then
                    return checkInt(a.vo.quality) > checkInt(b.vo.quality)
                end
                return checkInt(a.num) > checkInt(b.num)
            end)
        end
    end
end

---处理参数
function WorktableDialog:InitArgument()
    local parameters = self.controller.Argument.parameters
    if not parameters or not parameters.index then return end
    
    
    local goodsId = checkInt(parameters.goodsId)
    local index = checkInt(parameters.index)
    self:SetSelectedTabIndex(index)
    local worktableData = self:GetWorktableData()
    self._selectGainId = goodsId
    for i, v in ipairs(worktableData[index]) do
        if checkInt(v.gainId) == goodsId then
            self:SetSelectedItemIndex(i)
            self._isJump = true
            self.controller.Argument.parameters = nil
            return 
        end
    end
end

