---初始化工作台数据
function WorktableDialog:InitWorktableData()
    local worktableData = {}
    for _, v in ipairs(TabConfigs) do
        local data = {}
        if v.type == TabType.CRAFT then
            data = self:InitCraftData()
        elseif v.type == TabType.CONVERT then
            data = self:InitConvertData()
        elseif v.type == TabType.FUSION then
