---初始化兑换数据
function WorktableDialog:InitConvertData()
    local setting = CfUtils.GetCf(AutoIds.IdSetting411, "MatCompositeVo", true)
    local data = {}
    for _, v in ipairs(setting) do
        if checkInt(v.type2) == TabType.CONVERT then
            if data[v.gainId] then
                table.insert(data[v.gainId], v)
            else
                data[v.gainId] = {v}
            end
        end
    end
    local keys = sortByKey(data, false)
    local t = {}
    for _, id in pairs(keys) do
        local tmp = {
            gainId = data[id][1].gainId,
            children = data[id]
        }
        table.insert(t, tmp)
    end
    return t
end

---初始化卡牌融合数据
function WorktableDialog:InitFusionData()
    local backpackComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)

    local cores = {}
    local totalData = backpackComponent:GetGoodsByTypeId(Constants.IDType.GoodsSameCard)
    for _, v in ipairs(totalData) do
        if checkInt(v.num) > 0 and not CardComp:IsHasCard(v.vo.cardId) then
            local tmp = {
                gainId =  v.vo.cardId,
                vo = v.vo,
                num = v.num,
                goodsId = v.goodsId
            }
            table.insert(cores, tmp)
        end
    end
    
    return cores
end

