    self:RefreshTab()
    self:RefreshFilterNodeType()
    self:RefreshFilterNode()
end

---OnGetItemByIndex
---@param idx number
function WorktableDialog:OnGetItemByIndex(cell, idx)
    if idx < 0 then return nil end

    local index = idx + 1
    local nodeEnv = self:GetCellScr(cell)
    if isNull(nodeEnv) then return nil end
    
    local data = self:GetFilteredData()
    local tabType = self:GetTabType()
    local goodsId = data[index].gainId
    if tabType == TabType.FUSION then
        goodsId = data[index].goodsId
    end
    nodeEnv:RefreshCell(goodsId, index, Bind(self, self.CellOnClickHandler))
    nodeEnv:SetCheckState(index == self:GetSelectedItemIndex())
    
    if tabType == TabType.CRAFT then
        nodeEnv:SetGreyState(self:GetMaxCraftTimes(data[index].gainId) == 0) 
        nodeEnv:SetRedPointState(false)
    elseif tabType == TabType.CONVERT then
        nodeEnv:SetGreyState(not self:CheckConvert(data[index]))
        nodeEnv:SetRedPointState(false)
    elseif tabType == TabType.FUSION then
        local state = checkInt(data[index].num) >= checkInt(data[index].vo.needNum)
        nodeEnv:SetGreyState(not state)
        nodeEnv:SetRedPointState(state)
    elseif tabType == TabType.DustSynthesis then
        nodeEnv:SetGreyState(self:GetMaxCraftTimes(data[index].gainId) == 0) 
        nodeEnv:SetRedPointState(false) 
    end

    return cell
end
