---筛选按钮点击回调
function WorktableDialog:OnClickFilterCellHandler(data)
    self:SetFilteredData(data)
    if self._isJump then
        self:ClearConvertMaterial()
        self:RefreshListView()
        self.ScrollView:MovePanelToItemIndex(self:GetSelectedItemIndex() - 1)
        self._isJump = false
    else
        self:SetSelectedItemIndex(1)
        self:ClearConvertMaterial()
        self:RefreshListView()
        self.ScrollView:MovePanelToItemIndex(0)
    end
    self:RefreshRightPanel()
end

---cell点击回调
function WorktableDialog:CellOnClickHandler(index)
    local oldCell = self.ScrollView:GetShownItemByItemIndex(self:GetSelectedItemIndex() - 1)
    local oldCellScr = self:GetCellScr(oldCell)
    if not isNull(oldCellScr) then
        oldCellScr:SetCheckState(false)
    end
    self:SetSelectedItemIndex(index)
    local cell = self.ScrollView:GetShownItemByItemIndex(index - 1)
    local scr = self:GetCellScr(cell)
    if not isNull(scr) then
        scr:SetCheckState(true)
    end

    if self:GetTabType() == TabType.CONVERT then
        self:ClearConvertMaterial()
    elseif self:GetTabType() == TabType.FUSION then
        self:ClearConvertMaterial()
    end
    self:RefreshRightPanel()
end

