    GameUtils.ShowCommonGoodsTipsBoard(self.ImgGoodsIcon, goodsId, true)
end

---按钮点击回调
function WorktableDialog:BtnOnClickHandler()
    if not self:GetFilteredData()[self:GetSelectedItemIndex()] then return end
    
    local tabType = self:GetTabType()
    if tabType == TabType.CRAFT or tabType == TabType.DustSynthesis  then
        if self:GetCraftAmount() == 0 then
            GameUtils.Toast(localize("材料不足"))
            return 
        end
    elseif tabType == TabType.CONVERT then
        local data = self:GetConvertMaterial()
        if not next(data) then
            GameUtils.Toast(localize("请选择材料"))
            return
        end
    elseif tabType == TabType.FUSION then
        local data = self:GetFilteredData()[self:GetSelectedItemIndex()]
        if checkInt(data.num) < checkInt(data.vo.needNum) then
            GameUtils.Toast(localize("材料不足"))
            return
        end
    end

    if self._aniCo ~= nil then
        cs_coroutine.stop(self._aniCo)
    end
    self._aniCo = cs_coroutine.start(function()
        UIRaycastBlocker:AddCondition("WorktableDialog")
        CfUtils.PlayAnimation(self.GoodsBg, "OverseaStoreCoreExchangeDialog_Goods_Active")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.9))
        CfUtils.PlayAnimation(self.GoodsBg, "OverseaStoreCoreExchangeDialog_Goods_Idle")
        UIRaycastBlocker:RemoveCondition("WorktableDialog")

        if tabType == TabType.CRAFT or tabType == TabType.DustSynthesis then
            local data = self:GetFilteredData()[self:GetSelectedItemIndex()]
            if checkNumber(data.costItem) >= 770000000 and checkNumber(data.costItem) < 779999999 then
                -- 77同卡粉尘道具表
                GameUtils.Request(Interfaces.BackpackCardDustComposite, { id = data.costItem , num = self:GetCraftAmount()}, Bind(self, self.CraftResponseHandler))
            else
                -- oth:
                GameUtils.Request(Interfaces.BackpackComposite, {
                    id = data.id, num = self:GetCraftAmount()
                }, Bind(self, self.CraftResponseHandler))
            end

        elseif tabType == TabType.CONVERT then
            local data = self:GetConvertMaterial()
            GameUtils.Request(Interfaces.BackpackComposite, {
                id = data.id, num = self:GetConvertAmount()
            }, Bind(self, self.ConvertResponseHandler))
            
        elseif tabType == TabType.FUSION then
            local data = self:GetFilteredData()[self:GetSelectedItemIndex()]
            GameUtils.Request(Interfaces.OverseaCardComposite, {
                cardId = data.gainId, num = 1
            }, Bind(self, self.FusionResponseHandler))
        end
    end)
end

---转换材料按钮点击回调
function WorktableDialog:ConvertConsumeBtnOnClickHandler()
