    UIModule.OpenDialog({ id = Constants.UITypeIds.ConvertChooseMaterialPopup, parameters = {data = data} })
end

---合成请求回调处理
function WorktableDialog:CraftResponseHandler(request, responseTable)
    local goodsId = self:GetSelectedGoodsId()
    local consume = self:GetCraftConsume(goodsId, self:GetCraftAmount())
    for _, v in ipairs(consume) do
        v.num = -v.num
    end
    GoodsUtils.DrawRewards(consume)
    local responseData = checkTable(responseTable.data)
    if isSet(responseData, "rewards") then
        GoodsUtils.DrawRewards(responseData.rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
        self:RefreshListView()
        self:RefreshRightPanel()
    end
end

---转换请求回调处理
function WorktableDialog:ConvertResponseHandler(request, responseTable)
    local data = self:GetConvertMaterial()
    local consume = {
        {goodsId = data.costItem, num = -self:GetConvertAmount() * checkInt(data.costItemNum)}
    }
    GoodsUtils.DrawRewards(consume)
    local responseData = checkTable(responseTable.data)
    if isSet(responseData, "rewards") then
        GoodsUtils.DrawRewards(responseData.rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
        self:ClearConvertMaterial()
        self:RefreshListView()
        self:RefreshRightPanel()
    end
end

---卡牌合成回调处理
function WorktableDialog:FusionResponseHandler(request, responseTable)
    local data = self:GetFilteredData()[self:GetSelectedItemIndex()]
    local consume = {
        {goodsId = data.goodsId, num = -checkInt(data.vo.needNum)}
    }
    GoodsUtils.DrawRewards(consume)
    local responseData = checkTable(responseTable.data)
    if isSet(responseData, "rewards") then
        GoodsUtils.DrawRewards(responseData.rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
        self:InitWorktableData()
        self:SortWorktableData()
        local oriData = clone(self:GetWorktableData()[self:GetSelectedTabIndex()])
        self:OnClickFilterCellHandler(oriData)
    end
end

