--region public
---刷新页面
function WorktableDialog:FreshUI(goodsId, index)
    self:SetSelectedTabIndex(checkInt(index))
    local worktableData = self:GetWorktableData()
    for i, v in ipairs(worktableData[checkInt(index)]) do
        if checkInt(v.gainId) == goodsId then
            self:SetSelectedItemIndex(i)
            self._isJump = true
            self:InitUI()
            return
        end
    end
end
