---刷新页签
function WorktableDialog:RefreshTab()
    local scr = CfUtils.GetLuaScr(self.CommonTabToggleLeft, "Game.UI.Worktable.WorktableTabToggleLeft")
    if scr then
        scr:FillToggles(self:GetTabData(), self:GetSelectedTabIndex())
    end
end

---刷新过滤按钮类型
function WorktableDialog:RefreshFilterNodeType()
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, "Game.Behaviours.UICommonFilterMB")
    if nodeEnv == nil then return end

    local tabType = self:GetTabType()
    if tabType == TabType.CRAFT then
        nodeEnv:SetFilterClass(Constants.UIFilterType.MaterialCraft)
    elseif tabType == TabType.CONVERT then
        nodeEnv:SetFilterClass(Constants.UIFilterType.MaterialConvert)
    elseif tabType == TabType.FUSION then
        return
    end
    nodeEnv:SetStyleType(2)
end

---刷新过滤按钮
function WorktableDialog:RefreshFilterNode()
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, "Game.Behaviours.UICommonFilterMB")
    if nodeEnv == nil then return end

    local tabType = self:GetTabType()
    local oriData = clone(self:GetWorktableData()[self:GetSelectedTabIndex()])
    if tabType == TabType.FUSION then
        CfUtils.SetActive(self.CommonFilterNode, false)
        self:OnClickFilterCellHandler(oriData)
        return 
    elseif tabType == TabType.DustSynthesis then
        CfUtils.SetActive(self.CommonFilterNode, false)     
    else
        CfUtils.SetActive(self.CommonFilterNode, true)
    end
    nodeEnv:SetCallback(oriData, Bind(self, self.OnClickFilterCellHandler), Constants.UISortType.Convert)
    nodeEnv:RestoreState("WorktableDialog" .. tabType, Bind(self, self.OnClickFilterCellHandler))
end

---刷新列表
function WorktableDialog:RefreshListView()
    local data = self:GetFilteredData()
    if not self.ScrollView.mLoopListView.IsListViewInit then
        self.ScrollView:InitListView(#data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #data)
    end
    CfUtils.SetActive(self.EmptyNode, next(checkTable(data)) == nil)
    CardComp:UpdateCardDustRedPoint()
    CardComp:UpdateCardFusionRedPoint()    
end

---刷新右侧界面
function WorktableDialog:RefreshRightPanel()
    self:RefreshTargetItem()
    self:RefreshConsume()
    self:RefreshBtn()
end

---刷新目标道具
function WorktableDialog:RefreshTargetItem()
    if self:GetFilteredData()[self:GetSelectedItemIndex()] then
        CfUtils.SetActive(self.TextName, true)
        CfUtils.SetActive(self.ImgGoodsIcon, true)
        CfUtils.SetActive(self.StarGroup, true)
        CfUtils.SetActive(self.ImgRare, true)
    else
        CfUtils.SetActive(self.TextName, false)
        CfUtils.SetActive(self.ImgGoodsIcon, false)
        CfUtils.SetActive(self.StarGroup, false)
        CfUtils.SetActive(self.ImgRare, false)
        CfUtils.SetActive(self.ConvertRoot, true)
        CfUtils.SetActive(self.ForgeRoot, false)
        CfUtils.SetActive(self.CurrentNumber, false)
        return
    end
    
    local goodsId = self:GetFilteredData()[self:GetSelectedItemIndex()].gainId
    local goodsVo = GoodsConfMgrIns:GetGoodsVoById(goodsId)
    CfUtils.FillText(self.TextName, goodsVo.name)
    CfUtils.SetUISwitchImage(self.ImgRare, goodsVo.quality)
    for _, v in ipairs(self._starGroup) do
        CfUtils.SetActive(v, false)
    end
    -- 星级
    for i = 1, checkInt(goodsVo.quality) do
        if self._starGroup[i] then
            CfUtils.SetActive(self._starGroup[i], true)
        else
            if i == 1 then
                CfUtils.SetActive(self.ImgStar, true)
                table.insert(self._starGroup, self.ImgStar)
            else
                local star = self.StarGroup.gameObject:AddChild(self.ImgStar.gameObject)
                table.insert(self._starGroup, star)
            end
        end
    end
    CfUtils.FillImage(self.ImgGoodsIcon, goodsVo.photoPath)
    CfUtils.SetActive(self.ImgGoodsIcon, true)
    local num = GoodsUtils.GetThingNo(goodsId)
    CfUtils.FillText(self.TextNumber, num)
    
    local tabType = self:GetTabType()
    if tabType == TabType.CRAFT then
        CfUtils.SetActive(self.ConvertRoot, true)
        CfUtils.SetActive(self.ForgeRoot, false)
        CfUtils.SetActive(self.CurrentNumber, true)
    elseif tabType == TabType.CONVERT then
        CfUtils.SetActive(self.ConvertRoot, false)
        CfUtils.SetActive(self.ForgeRoot, true)
        CfUtils.SetActive(self.CurrentNumber, true)
    elseif tabType == TabType.FUSION then
        CfUtils.SetActive(self.ConvertRoot, true)
        CfUtils.SetActive(self.ForgeRoot, false)
        CfUtils.SetActive(self.CurrentNumber, false)
    end
end

---刷新消耗
function WorktableDialog:RefreshConsume()
    if self:GetFilteredData()[self:GetSelectedItemIndex()] then
        CfUtils.SetActive(self.TextEmpty, false)
    else
        CfUtils.SetActive(self.TextEmpty, true)
        CfUtils.SetActive(self.QuantitySlider, false)
        CfUtils.SetActive(self.Convert, false)
        CfUtils.SetActive(self.Exchange, false)
        CfUtils.SetActive(self.NotEnough, false)
        return
    end
    
    local tabType = self:GetTabType()
    if tabType == TabType.CRAFT or tabType == TabType.DustSynthesis then
        self:RefreshCraftConsume()
    elseif tabType == TabType.CONVERT then
        self:RefreshConvertConsume()
    elseif tabType == TabType.FUSION then
        self:RefreshFusionConsume()
    end
end

---刷新合成消耗
function WorktableDialog:RefreshCraftConsume()
    local goodsId = self:GetSelectedGoodsId()
    local maxNum = self:GetMaxCraftTimes(goodsId)
    print("maxNum =>" ,maxNum)
    self:RefreshCraftSlider(maxNum)
    self:RefreshCraftConsumeList(goodsId, 1)
end

---刷新合成消耗列表
---@param goodsId integer 道具id
---@param goodsNum integer 道具数量
function WorktableDialog:RefreshCraftConsumeList(goodsId, goodsNum)
    local consume, canCraft = self:GetCraftConsume(goodsId, goodsNum)
    CfUtils.SetActive(self.Convert, true)
    CfUtils.SetActive(self.Exchange, false)

    for _, v in ipairs(self._craftMaterialGroup) do
        CfUtils.SetActive(v, false)
    end

    for i, v in ipairs(consume) do
        if self._craftMaterialGroup[i] then
            self:RefreshCraftConsumeGoods(self._craftMaterialGroup[i], v, canCraft)
            CfUtils.SetActive(self._craftMaterialGroup[i], true)
        else
            if i == 1 then
                self:RefreshCraftConsumeGoods(self.ConvertGoods, v, canCraft)
                CfUtils.SetActive(self.ConvertGoods, true)
                table.insert(self._craftMaterialGroup, self.ConvertGoods)
            else
                local goodsNode = self.ConvertLayout.gameObject:AddChild(self.ConvertGoods.gameObject)
                self:RefreshCraftConsumeGoods(goodsNode, v, canCraft)
                table.insert(self._craftMaterialGroup, goodsNode)
            end
        end
    end
end

---刷新合成消耗道具
function WorktableDialog:RefreshCraftConsumeGoods(go, goodsData, canCraft)
    local goodsNode = go.transform:Find("GoodNode")
    local strFmt = "%s/%s"
    if not canCraft then
        strFmt = "<color=#ff0000>%s</color>/%s"
    end
    local num = string.format(strFmt, GoodsUtils.GetThingNo(goodsData.goodsId), goodsData.num)

    CfUtils.RefeshGoodGo2(goodsNode, goodsData.goodsId, num)
end

---刷新合成滑动条
---@param maxNum integer 滑动最大值
function WorktableDialog:RefreshCraftSlider(maxNum)
    CfUtils.SetActive(self.TipsSynthesis,false)
    if maxNum == 0 then
        CfUtils.SetActive(self.NotEnough, true)
        CfUtils.SetUISwitchText(self.NotEnoughTextDesc, 1)
        CfUtils.SetActive(self.QuantitySlider, false)
        self:SetCraftAmount(0)
        return
    end
    
    CfUtils.SetActive(self.NotEnough, false)
    CfUtils.SetActive(self.QuantitySlider, true)
    local scr = CfUtils.GetLuaScr(self.QuantitySlider, "Game.UI.Common.CommonSliderNode")
    if isNull(scr) then return end

    scr:RefreshNode(
            1,
            1,
            maxNum,
            Bind(self, self.SliderOnValueChangedHandler)
    )
    self:SetCraftAmount(1)
end

---刷新按钮
function WorktableDialog:RefreshBtn()
    local tabType = self:GetTabType()
    local redPoint = self.FontStyleButton.transform:Find("redPoint")
    if tabType == TabType.CRAFT then
        CfUtils.SetActive(self.TipsSynthesis, false)
        CfUtils.FillText(self.ButtonText, localize("合成"))
        CfUtils.SetActive(redPoint, false)
    elseif tabType == TabType.CONVERT then
        CfUtils.SetActive(self.TipsSynthesis, false)
        CfUtils.FillText(self.ButtonText, localize("置换"))
        CfUtils.SetActive(redPoint, false)
    elseif tabType == TabType.FUSION then
        CfUtils.SetActive(self.TipsSynthesis, true)
        CfUtils.FillText(self.ButtonText, localize("合成"))
        local data = self:GetFilteredData()[self:GetSelectedItemIndex()]
        if data and checkInt(data.num) >= checkInt(data.vo.needNum) then
            CfUtils.SetActive(redPoint, true)
        else
            CfUtils.SetActive(redPoint, false)
        end
    end

    if self:GetFilteredData()[self:GetSelectedItemIndex()] then
        self.FontStyleButton:ResetFontStyle("B5")
    else
        self.FontStyleButton:ResetFontStyle("B17")
    end
end

---滑动条变动
function WorktableDialog:SliderValueChanged(value)
    if self:GetTabType() == TabType.CRAFT or self:GetTabType() == TabType.DustSynthesis then
        local goodsId = self:GetSelectedGoodsId()
        self:SetCraftAmount(value)
        self:RefreshCraftConsumeList(goodsId, value)
    elseif self:GetTabType() == TabType.CONVERT then
        self:SetConvertAmount(value)
        self:RefreshConvertConsumeList()
    end
end

---刷新转换消耗
function WorktableDialog:RefreshConvertConsume()
    self:RefreshConvertSlider()
    self:RefreshConvertConsumeList()
end

---刷新转换滑动条
function WorktableDialog:RefreshConvertSlider()
    local materialData = self:GetConvertMaterial()
    local goodsId = checkInt(materialData.costItem)
    CfUtils.SetActive(self.TipsSynthesis,false)
    if goodsId == 0 then
        CfUtils.SetActive(self.NotEnough, true)
        CfUtils.SetUISwitchText(self.NotEnoughTextDesc, 2)
        CfUtils.SetActive(self.QuantitySlider, false)
        self:SetConvertAmount(0)
        return 
    end
    
    CfUtils.SetActive(self.NotEnough, false)
    CfUtils.SetActive(self.QuantitySlider, true)
    local scr = CfUtils.GetLuaScr(self.QuantitySlider, "Game.UI.Common.CommonSliderNode")
    if isNull(scr) then return end

    local maxNum = math.floor(GoodsUtils.GetThingNo(goodsId) / checkInt(materialData.costItemNum))
    scr:RefreshNode(
            1,
            1,
            maxNum,
            Bind(self, self.SliderOnValueChangedHandler)
    )
    self:SetConvertAmount(1)
end

---刷新转换列表
function WorktableDialog:RefreshConvertConsumeList()
    CfUtils.SetActive(self.Convert, false)
    CfUtils.SetActive(self.Exchange, true)
    local materialData = self:GetConvertMaterial()
    local goodsId = checkInt(materialData.costItem)
    if goodsId == 0 then
        CfUtils.SetActive(self.ExchangeImgAdd, true)
        CfUtils.SetActive(self.ExchangeLayout, false)
        return
    end

    CfUtils.SetActive(self.ExchangeImgAdd, false)
    CfUtils.SetActive(self.ExchangeLayout, true)
    local num = string.format("%d/%d", GoodsUtils.GetThingNo(materialData.costItem), materialData.costItemNum * self:GetConvertAmount())
    CfUtils.RefeshGoodGo2(self.ExchangeGoodNode, materialData.costItem, num, nil, nil, function()
        local data = self:GetFilteredData()[self:GetSelectedItemIndex()]
        UIModule.OpenDialog({ id = Constants.UITypeIds.ConvertChooseMaterialPopup, parameters = {data = data} })
    end)
end

---清除过滤器
function WorktableDialog:CloseFilter()
    if self:GetTabType() == TabType.FUSION then return end 
    
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, "Game.Behaviours.UICommonFilterMB")
    if not isNull(nodeEnv) then
        nodeEnv:OnCloseFilterButtonAction()
    end
end

---清除转换材料
function WorktableDialog:ClearConvertMaterial()
    self:SetConvertMaterial({})
end

---检查道具是否可以转换
---@param convertData table 转换道具数据
function WorktableDialog:CheckConvert(convertData)
    for _, v in ipairs(checkTable(convertData.children)) do
        if GoodsUtils.GetThingNo(v.costItem) >= checkInt(v.costItemNum) then
            return true
        end
    end
    return false
end

---刷新卡牌合成消耗
function WorktableDialog:RefreshFusionConsume()
    CfUtils.SetActive(self.QuantitySlider, false)
    CfUtils.SetActive(self.Convert, true)
    CfUtils.SetActive(self.Exchange, false)
    CfUtils.SetActive(self.NotEnough,false)
    CfUtils.SetActive(self.TipsSynthesis,true)

    for _, v in ipairs(self._craftMaterialGroup) do
        CfUtils.SetActive(v, false)
    end
    
    local data = self:GetFilteredData()[self:GetSelectedItemIndex()]
    local needNum = checkInt(data.vo.needNum)
    self:RefreshCraftConsumeGoods(self.ConvertGoods, {goodsId = data.goodsId, num = needNum}, checkInt(data.num) >= needNum)
    CfUtils.SetActive(self.ConvertGoods, true)
end
