---设置过滤后的数据
---@param filteredData table 过滤后的数据
function WorktableDialog:SetFilteredData(filteredData)
    if self:GetSelectedTabIndex() == TabType.CRAFT then
        ---合成
        table.sort(filteredData, function(a, b)
            ---为了速度不再取道具类型表
            local aType, bType = checkNumber(a.id),checkNumber(b.id)
            if checkNumber(a.costItem) >= 770000000 and checkNumber(a.costItem) < 779999999 then
                aType = 1
            end
            if checkNumber(b.costItem) >= 770000000 and checkNumber(b.costItem) < 779999999 then
                bType = 1
            end
            return aType < bType
        end)
    elseif self:GetSelectedTabIndex() == TabType.DustSynthesis then
        table.sort(filteredData , function (a, b)
            return a.id < b.id
        end)
    end
    self._filteredData = checkTable(filteredData)
    if checkInt(self._selectGainId) > 0  then
        for k, v in pairs(filteredData) do
            if checkInt(v.gainId)  == self._selectGainId then
                self._selectGainId = 0
               
                self:SetSelectedItemIndex(k)
                break
            end
        end
    end
end

