---获取最大合成次数
---@param goodsId integer 道具id
---@param num integer | nil 前置道具数量
---@param ratio integer | nil 前置道具兑换比例
function WorktableDialog:GetMaxCraftTimes(goodsId, num, ratio)
    local craftData
    if self:GetTabType() == TabType.CRAFT then
        craftData = self:GetCraftData(goodsId)  
    elseif self:GetTabType() == TabType.DustSynthesis then
        craftData = self:GetDustSynthesisData(goodsId)  
    end
    if craftData then
        local cNum = checkInt(craftData.costItemNum) * checkInt(num) + GoodsUtils.GetThingNo(craftData.costItem)
        local cRatio = checkInt(craftData.costItemNum)
        if ratio then
            cRatio = cRatio * checkInt(ratio)
        end
        return self:GetMaxCraftTimes(craftData.costItem,  cNum, cRatio)
    end

    if (not num) or (not ratio) then
        return 0
    else
        return math.floor(checkInt(num) / checkInt(ratio))
    end
end

---获取合成消耗
---@param goodsId integer 道具id
---@param goodsNum integer 道具数量
---@param exParams table | nil 额外参数
--- * origin table 原始合成条件
--- * result table 前置合成消耗
---@return table, boolean 道具列表, 是否可以合成
function WorktableDialog:GetCraftConsume(goodsId, goodsNum, exParams)
    local params = checkTable(exParams)
    local totalData = self:GetWorktableData()[self:GetSelectedTabIndex()]
    local targetData = nil
    for _, v in ipairs(totalData) do
        if goodsId == v.gainId then
            targetData = v
            break
        end
    end

    if targetData then
        -- 可以被合成
        local num = GoodsUtils.GetThingNo(targetData.costItem)
        local costNum = checkInt(targetData.costItemNum) * goodsNum
        params.result = checkTable(params.result)
        local result = params.result
        if num >= costNum then
            -- 材料满足
            local t = {
                goodsId = targetData.costItem,
                num = costNum
            }
            table.insert(result, t)
            return result, true
        else
            if num > 0 then
                local t = {
                    goodsId = targetData.costItem,
                    num = num
                }
                table.insert(result, t)
            end
            if not params.origin then
                -- 记录原始数据
                params.origin = {{
                                     goodsId = targetData.costItem,
                                     num = costNum
                                 }}
            end
            return self:GetCraftConsume(targetData.costItem, costNum - num, params)
        end
    end

    -- 无法被合成
    return params.origin or {}, false
end

